  return {id:$row.id,path:$row.path,start_line:$row.start_line,end_line:$row.end_line,numbered:$row.numbered,
    excerpt:$r.text,total_lines:get($r.data,"total_lines"),observation_ref:$ref,claim:$row.claim,note:$n}
}
return $m.data.rows >> [table:each]{ [fn:처리]{row:$it} }
